// Recibe el array de productos del endpoint de Valmont
const raw = $input.first().json;
const products = Array.isArray(raw) ? raw : Object.values(raw);

if (!products || products.length === 0) {
  throw new Error('No hay productos con stock publicados');
}

// Mezclar y elegir 5 a 7 productos al azar
const shuffled = [...products].sort(() => Math.random() - 0.5);
const count = Math.min(Math.floor(Math.random() * 3) + 5, shuffled.length); // 5, 6 o 7
const selected = shuffled.slice(0, count);

const emojis = {
  remeras: '👕',
  pantalones: '👖',
  buzos: '🧥',
  accesorios: '💍',
  calzado: '👟',
};

return selected.map((p, i) => ({
  json: {
    id:              p.id,
    name:            p.name,
    category:        p.category,
    price_sale:      p.price_sale,
    image_url:       p.image_url,
    index:           i + 1,
    total:           count,
    emoji:           emojis[p.category] || '🛍️',
    price_formatted: new Intl.NumberFormat('es-AR', {
      style:                 'currency',
      currency:              'ARS',
      minimumFractionDigits: 0,
    }).format(p.price_sale),
  },
}));

const p = $input.item.json;
const HF_TOKEN  = $env.HF_TOKEN;
const TG_TOKEN  = $env.INSTAGRAM_TG_BOT_TOKEN;
const TG_CHAT   = $env.INSTAGRAM_TG_CHAT_ID;

// ─── helpers ────────────────────────────────────────────────
function buildMultipart(chatId, caption, imgBuffer, filename) {
  const b    = `----ValmontBound${Date.now()}`;
  const crlf = '\r\n';
  const body = Buffer.concat([
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="chat_id"${crlf}${crlf}${chatId}${crlf}`),
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="parse_mode"${crlf}${crlf}Markdown${crlf}`),
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="caption"${crlf}${crlf}${caption}${crlf}`),
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="photo"; filename="${filename}"${crlf}Content-Type: image/jpeg${crlf}${crlf}`),
    imgBuffer,
    Buffer.from(`${crlf}--${b}--${crlf}`),
  ]);
  return { body, ct: `multipart/form-data; boundary=${b}` };
}

async function tgSendPhoto(imgBuffer, caption, filename) {
  const { body, ct } = buildMultipart(TG_CHAT, caption, imgBuffer, filename);
  const r = await fetch(`https://api.telegram.org/bot${TG_TOKEN}/sendPhoto`, {
    method: 'POST',
    headers: { 'Content-Type': ct },
    body,
  });
  if (!r.ok) throw new Error(`Telegram sendPhoto error: ${await r.text()}`);
}

async function hfPix2Pix(imageBase64, prompt) {
  for (let attempt = 0; attempt < 6; attempt++) {
    const r = await fetch(
      'https://api-inference.huggingface.co/models/timbrooks/instruct-pix2pix',
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${HF_TOKEN}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          inputs: imageBase64,
          parameters: {
            prompt,
            negative_prompt: 'ugly, blurry, low quality, watermark, text, logo, distorted, duplicate',
            num_inference_steps: 25,
            image_guidance_scale: 1.5,
            guidance_scale: 7.5,
          },
        }),
      }
    );

    if (r.status === 503) {
      const err = await r.json().catch(() => ({}));
      const wait = Math.min((err.estimated_time ?? 30) * 1000, 90000);
      await new Promise((res) => setTimeout(res, wait));
      continue;
    }

    if (!r.ok) throw new Error(`HF error ${r.status}: ${await r.text()}`);
    return Buffer.from(await r.arrayBuffer());
  }
  throw new Error('HF: máximo de reintentos alcanzado');
}

// ─── 1. Descargar imagen del producto ───────────────────────
const imgResp = await fetch(p.image_url);
if (!imgResp.ok) throw new Error(`No se pudo descargar imagen: ${p.image_url}`);
const imgBase64 = Buffer.from(await imgResp.arrayBuffer()).toString('base64');

// ─── 2. Generar imagen estilo STORY (flat lay en piso de cemento) ─
const storyPrompt =
  `Place this ${p.category} clothing item as a flat lay on a polished textured concrete floor, ` +
  `overhead composition, dramatic studio lighting from above, minimalist fashion editorial, ` +
  `high detail, sharp focus, professional product photography`;

const storyBuffer = await hfPix2Pix(imgBase64, storyPrompt);

// ─── 3. Armar caption para la story ─────────────────────────
const name = p.name.replace(/[_*[\]()~`>#+=|{}.!-]/g, '\\$&'); // escape Markdown
const storyCaption =
  `📱 *HISTORIA ${p.index}/${p.total}*\n\n` +
  `${p.emoji} *${name.toUpperCase()}*\n` +
  `💵 ${p.price_formatted}\n\n` +
  `✨ Últimas unidades disponibles\n` +
  `🛒 valmont\-jarg\.com\n\n` +
  `#valmont #streetwear #moda #style #argentina`;

// ─── 4. Enviar story a Telegram ──────────────────────────────
await tgSendPhoto(storyBuffer, storyCaption, `story_${p.index}.jpg`);

// ─── 5. Generar imagen estilo CARRUSEL (editorial, modelo) ───
const carouselPrompt =
  `Fashion model confidently wearing this exact ${p.category} clothing item, ` +
  `urban concrete background, energetic lifestyle photography, candid editorial pose, ` +
  `vibrant fun composition, high quality commercial photography`;

const carouselBuffer = await hfPix2Pix(imgBase64, carouselPrompt);

// ─── 6. Retornar datos del carrusel para el paso siguiente ───
return [{
  json: {
    product_name:           p.name,
    price_formatted:        p.price_formatted,
    emoji:                  p.emoji,
    index:                  p.index,
    total:                  p.total,
    carousel_image_base64:  carouselBuffer.toString('base64'),
  },
}];

const items    = $input.all();
const TG_TOKEN = $env.INSTAGRAM_TG_BOT_TOKEN;
const TG_CHAT  = $env.INSTAGRAM_TG_CHAT_ID;

// ─── helpers ────────────────────────────────────────────────
async function tgMsg(text) {
  await fetch(`https://api.telegram.org/bot${TG_TOKEN}/sendMessage`, {
    method:  'POST',
    headers: { 'Content-Type': 'application/json' },
    body:    JSON.stringify({ chat_id: TG_CHAT, parse_mode: 'Markdown', text }),
  });
}

async function tgSendPhoto(imgBuffer, caption, filename, i) {
  const b    = `----ValmontCarrusel${Date.now()}${i}`;
  const crlf = '\r\n';
  const body = Buffer.concat([
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="chat_id"${crlf}${crlf}${TG_CHAT}${crlf}`),
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="parse_mode"${crlf}${crlf}Markdown${crlf}`),
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="caption"${crlf}${crlf}${caption}${crlf}`),
    Buffer.from(`--${b}${crlf}Content-Disposition: form-data; name="photo"; filename="${filename}"${crlf}Content-Type: image/jpeg${crlf}${crlf}`),
    imgBuffer,
    Buffer.from(`${crlf}--${b}--${crlf}`),
  ]);
  const r = await fetch(`https://api.telegram.org/bot${TG_TOKEN}/sendPhoto`, {
    method:  'POST',
    headers: { 'Content-Type': `multipart/form-data; boundary=${b}` },
    body,
  });
  if (!r.ok) console.error(`Error foto carrusel ${i}:`, await r.text());
}

// ─── Cabecera del carrusel ───────────────────────────────────
await tgMsg(
  `🎠 *CARRUSEL DEL DÍA*\n\n` +
  `Subí estas *${items.length} fotos* como carrusel en Instagram con el caption de abajo 👇`
);
await new Promise((r) => setTimeout(r, 500));

// ─── Caption principal (para copiar y pegar) ─────────────────
const productLines = items.map((i) => `${i.json.emoji} ${i.json.product_name} — ${i.json.price_formatted}`).join('\n');
const mainCaption =
  `✨ SELECCIÓN DEL DÍA\n\n` +
  `${productLines}\n\n` +
  `🛒 Disponible en valmont-jarg.com\n` +
  `📦 Envíos a todo el país\n\n` +
  `#valmont #streetwear #moda #nuevacoleccion #outfits #style #argentina`;

await tgMsg(`📝 *CAPTION PARA EL CARRUSEL:*\n\`\`\`\n${mainCaption}\n\`\`\``);
await new Promise((r) => setTimeout(r, 500));

// ─── Fotos del carrusel ──────────────────────────────────────
for (let i = 0; i < items.length; i++) {
  const item      = items[i].json;
  const imgBuffer = Buffer.from(item.carousel_image_base64, 'base64');
  const caption   = `🎠 *Slide ${i + 1}/${items.length}* — ${item.emoji} ${item.product_name}`;

  await tgSendPhoto(imgBuffer, caption, `carousel_${i + 1}.jpg`, i);
  await new Promise((r) => setTimeout(r, 700));
}

// ─── Mensaje final ───────────────────────────────────────────
await tgMsg(
  `✅ *¡Listo para publicar!*\n\n` +
  `📱 ${items.length} historias enviadas\n` +
  `🎠 ${items.length} slides del carrusel\n\n` +
  `_Revisá las fotos y subílas cuando quieras\._`
);

return items;
